from html.parser import HTMLParser
import re

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_td = False
        self.current_row = []
        self.rows = []
        self.in_tr = False

    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            self.in_tr = True
            self.current_row = []
        elif tag == 'td' and self.in_tr:
            self.in_td = True

    def handle_endtag(self, tag):
        if tag == 'td':
            self.in_td = False
        elif tag == 'tr' and self.in_tr:
            self.rows.append(self.current_row)
            self.in_tr = False

def extract_bond_price(filename, coupon, maturity):
    """Extract bid price for a specific bond"""
    with open(filename) as f:
        content = f.read()

    parser = TableParser()
    parser.feed(content)

    # Find the row with the matching bond
    for row in parser.rows:
        row_str = ' '.join(row)
        # Look for 3-1/2% and 2/15/90
        if '3-1/2' in row_str and maturity in row_str:
            # The bid price should be in the 5th column (index 4)
            # Price format is XX.XX (32nds)
            if len(row) >= 5:
                # Find the price column - after the maturity date
                for i, cell in enumerate(row):
                    if re.match(r'^\d+\.\d+$', cell.strip()):
                        return cell.strip()
    return None

# Extract prices for each year
coupon = "3-1/2"
maturity = "2/15/90"

years = [1972, 1973, 1974, 1975, 1976]
prices = {}

for year in years:
    filename = f'/app/resources/treasury_bulletin_{year}_04_page_{89 if year == 1972 else 91 if year == 1973 else 88 if year <= 1975 else 104}.txt'
    price = extract_bond_price(filename, coupon, maturity)
    prices[year] = price
    print(f"Year {year}: Bid price = {price}")
